<?php namespace BinerMail;
class Security{public static function encrypt(string $plain):string{$key=self::key();$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt($plain,'aes-256-gcm',$key,OPENSSL_RAW_DATA,$iv,$tag);return base64_encode($iv.$tag.$cipher);}public static function decrypt(string $enc):string{$raw=base64_decode($enc,true);if($raw===false||strlen($raw)<28)throw new \RuntimeException('Invalid encrypted value');$plain=openssl_decrypt(substr($raw,28),'aes-256-gcm',self::key(),OPENSSL_RAW_DATA,substr($raw,0,12),substr($raw,12,16));if($plain===false)throw new \RuntimeException('Unable to decrypt');return $plain;}private static function key():string{$k=(string)config('key');if(!preg_match('/^[a-f0-9]{64}$/i',$k))throw new \RuntimeException('APP_KEY must be 64 hex characters');return hex2bin($k);}}
